11878:       } catch (error) {
11879:         if(error?.name==='AbortError')throw error;
11880:         recordDiagnostic('server-network-error',{label,path,attempt:attempt+1,error:error?.message || error});
11881:         if (attempt < retries) { const delay=SERVER_REQUEST_RETRY_DELAYS_MS[Math.min(attempt,SERVER_REQUEST_RETRY_DELAYS_MS.length-1)]; attempt += 1; await gameRetryDelay(delay); continue; }
11882:         recordDiagnostic('server-endpoint-unavailable',{revision:HK_SERVER_HEALTH_SCOPE_REV,label,path,kind:error?.name==='HKNetworkTimeout'?'timeout':'network'});
