11893:       if (transient && attempt < retries) {
11894:         const delay=SERVER_REQUEST_RETRY_DELAYS_MS[Math.min(attempt,SERVER_REQUEST_RETRY_DELAYS_MS.length-1)]; attempt += 1; await gameRetryDelay(delay); continue;
11895:       }
